@Configuration
public class AppConfig {
    @Bean
    public OrderService getOrder() {
        return new OrderService();
    }

    @Bean
    public OrderService getOrder2() {
        return new OrderService();
    }
}

public class Main {
    public static void main(String[] args) {
        ApplicationContext context = new AnnotationConfigApplicationContext(AppConfig.class);
        OrderService o1 = context.getBean("getOrder", OrderService.class);
        OrderService o2 = context.getBean("getOrder", OrderService.class);
        OrderService o3 = context.getBean("getOrder2", OrderService.class);
        System.out.println(o1 == o2);
        System.out.println(o1 == o3);
    }
}

@Component
@Scope("prototype")
public class Cart {
    private static int counter = 0;
    private final int id = ++counter;

    public Cart() {
        System.out.println("Cart created: " + id);
    }
    public int getId() { return id; }
}

@Component
public class CheckoutService {
    private final Cart cart;

    public CheckoutService(Cart cart) {
        this.cart = cart;
        System.out.println("CheckoutService created");
    }
    public void checkout() {
        System.out.println("Using cart " + cart.getId());
    }
}

public class Main {
    public static void main(String[] args) {
        ApplicationContext context = new AnnotationConfigApplicationContext(AppConfig.class);
        CheckoutService service = context.getBean(CheckoutService.class);
        service.checkout();
        service.checkout();
        System.out.println(context.getBean(Cart.class).getId());
    }
}

@Component
public class OrderService {
    PaymentService paymentService;

    public OrderService(@Lazy PaymentService paymentService) {
        this.paymentService = paymentService;
    }
    public void placeOrder() {
        paymentService.pay();
        System.out.println("Order placed");
    }
    public void getOrderDetails() {
        System.out.println("Order Details");
    }
}

@Component
@Lazy
public class PaymentService {
    OrderService orderService;

    public PaymentService(OrderService orderService) {
        this.orderService = orderService;
    }
    public void pay() {
        System.out.println("Payment successful");
        orderService.getOrderDetails();
    }
}

public class Main {
    public static void main(String[] args) {
        ApplicationContext context = new AnnotationConfigApplicationContext(AppConfig.class);
        OrderService order = context.getBean(OrderService.class);
        order.placeOrder();
    }
}
